      "/Users/samuel/Projects/exp-mocked-http/openspec/changes/http-mock-server/design.md"
    ],
    "tasks": [
      "/Users/samuel/Projects/exp-mocked-http/openspec/changes/http-mock-server/tasks.md"
    ]
  },
  "progress": {
    "total": 30,
    "complete": 0,
    "remaining": 30
  },
  "tasks": [
    {
      "id": "1",
      "description": "1.1 Create `pyproject.toml` with `jinja2` and `pyyaml` dependencies",
      "done": false
    },
    {
      "id": "2",
      "description": "1.2 Create empty `hmock.py` with shebang and top-level `main()` entry point",
      "done": false
    },
    {
      "id": "3",
      "description": "1.3 Create `templates/` directory with a sample YAML mock file for manual testing",
      "done": false
    },
    {
      "id": "4",
      "description": "2.1 Read and validate env vars: `HM_TEMPLATES_DIR`, `HM_HTTP_PORT`, `HM_HTTP_HOST`, `HM_LOG_LEVEL`",
      "done": false
    },
    {
      "id": "5",
      "description": "2.2 Implement structured JSON logger that honors `HM_LOG_LEVEL`",
      "done": false
    },
    {
      "id": "6",
      "description": "3.1 Implement recursive YAML scanner (sorted `os.walk`, `.yaml`/`.yml` files)",
      "done": false
    },
    {
      "id": "7",
      "description": "3.2 Parse each file as a list of behavior dicts and merge into one ordered list",
      "done": false
    },
    {
      "id": "8",
      "description": "3.3 Validate each behavior: `key` required and non-empty, `kind` defaults to `\"Behavior\"`, reject >1 `reply_http` action",
      "done": false
    },
    {
      "id": "9",
      "description": "3.4 Implement duplicate-key detection: last-wins replacement with warning log",
      "done": false
    },
    {
      "id": "10",
      "description": "4.1 Compile each behavior's `expect.http.path` from `:param` syntax to a named-group regex at load time",
      "done": false
    },
    {
      "id": "11",
      "description": "4.2 Implement `match_path(pattern, path)` returning captured params dict or None",
      "done": false
    },
    {
      "id": "12",
      "description": "5.1 Configure Jinja2 environment with `StrictUndefined` and `{{ }}` delimiters",
      "done": false
    },
    {
      "id": "13",
      "description": "5.2 Register extended functions: `contains`, `hasPrefix`, `hasSuffix`, `replace`, `trim`, `upper`, `lower`, `title`, `split`, `splitList`, `join`, `repeat`, `nospace`, `toString`, `default`, `empty`, `coalesce`, `ternary`, `b64enc`, `b64dec`, `env`, `add`, `sub`, `mul`, `div`, `mod`, `max`, `min`, `uuidv4`",
      "done": false
    },
    {
      "id": "14",
      "description": "5.3 Implement `render(template_str, context)` that replaces `\\r\\n`, `\\n`, `\\t` with spaces before parsing, then renders; returns `(result, error)`",
      "done": false
    },
    {
      "id": "15",
      "description": "5.4 Implement `HeaderMap` class with `.Get(name)` method usable from templates",
      "done": false
    },
    {
      "id": "16",
      "description": "6.1 Implement `build_context(request)` returning dict with `.HTTPHeader`, `.HTTPBody`, `.HTTPPath`, `.HTTPQueryString`",
      "done": false
    },
    {
      "id": "17",
      "description": "6.2 Implement `find_behavior(behaviors, method, path, context)` iterating in order: check method+path match, then render condition and check for exact `\"true\"`, return first match or None",
      "done": false
    },
    {
      "id": "18",
      "description": "6.3 Handle condition render errors by skipping the behavior (no match)",
      "done": false
    },
    {
      "id": "19",
      "description": "7.1 Implement `execute_sleep(action)`: parse duration string with unit support (`ns`, `us`, `ms`, `s`, `m`, `h`), sleep accordingly",
      "done": false
    },
    {
      "id": "20",
      "description": "7.2 Implement `execute_reply_http(action, context, handler)`: render body and each header value as templates, default `Content-Type: application/json`, set `Content-Length`, write response",
      "done": false
    },
    {
      "id": "21",
      "description": "7.3 Implement `execute_actions(actions, context, handler)` iterating the action list in order",
      "done": false
    },
    {
      "id": "22",
      "description": "8.1 Implement `MockRequestHandler(BaseHTTPRequestHandler)` with `do_METHOD` routing for all HTTP methods",
      "done": false
    },
    {
      "id": "23",
      "description": "8.2 On each request: build context, call `find_behavior`, execute actions or return 404 with body `not found`",
      "done": false
    },
    {
      "id": "24",
      "description": "8.3 Log each request/response pair at `info` with `http_path`, `http_method`, `http_host`, `http_req`, `http_res`",
      "done": false
    },
    {
      "id": "25",
      "description": "8.4 Start `HTTPServer` on configured host/port in `main()`",
      "done": false
    },
    {
      "id": "26",
      "description": "9.1 Verify `GET /ping` example from spec returns `200`, `Content-Type: text/plain`, `Content-Length: 2`, body `OK`",
      "done": false
    },
    {
      "id": "27",
      "description": "9.2 Verify condition routing example: `X-Token: t1234` returns 200, wrong token returns 401",
      "done": false
    },
    {
      "id": "28",
      "description": "9.3 Verify 404 response body is exactly `not found`",
      "done": false
    },
    {
      "id": "29",
      "description": "9.4 Verify duplicate key warning is logged and last definition wins",
      "done": false
    },
    {
      "id": "30",
      "description": "9.5 Verify `sleep` action delays response by the specified duration",
      "done": false
    }
  ],
  "state": "ready",
  "instruction": "Read context files, work through pending tasks, mark complete as you go.\nPause if you hit blockers or need clarification."
}

